#!/usr/bin/env python3
"""agent-0222 - independent sorter census + orbit structure audit (scratch)."""
import sys, time, argparse
from itertools import permutations, combinations

class Net:
    def __init__(self, n):
        self.n = n
        self.NV = 1 << n
        self.comps = [(i, j) for i in range(n) for j in range(i + 1, n)]
        self.m = len(self.comps)
        self.full = (1 << self.NV) - 1
        # sorted vectors: bit k = value on channel k, nondecreasing => 0..0 1..1
        sm = 0
        for t in range(n + 1):
            v = ((1 << n) - 1) ^ ((1 << t) - 1)
            sm |= 1 << v
        self.sortedmask = sm
        # per-comparator: mask of positions v with bit i =1, bit j =0 ; shift d
        self.amask = []
        self.shift = []
        for (i, j) in self.comps:
            A = 0
            for v in range(self.NV):
                if (v >> i) & 1 and not ((v >> j) & 1):
                    A |= 1 << v
            self.amask.append(A)
            self.shift.append((1 << j) - (1 << i))

    def apply(self, ci, S):
        A = self.amask[ci] & S
        if not A:
            return S
        return (S ^ A) | (A << self.shift[ci])

    # ---- counting: number of length-k ascending comparator SEQUENCES that sort
    def count(self, k):
        memo = {}
        n1 = self.n + 1
        sm = self.sortedmask
        pw = [1] * (k + 1)
        for t in range(1, k + 1):
            pw[t] = pw[t - 1] * self.m

        def rec(S, r):
            if not (S & ~sm):
                return pw[r]
            if r == 0:
                return 0
            pc = bin(S).count('1')
            # each comparator at most halves |S|; need |S| <= n+1 at the end
            need = 0
            x = pc
            while x > n1:
                x = (x + 1) // 2
                need += 1
            if need > r:
                return 0
            key = (S, r)
            got = memo.get(key)
            if got is not None:
                return got
            tot = 0
            for ci in range(self.m):
                T = self.apply(ci, S)
                if T != S:
                    tot += rec(T, r - 1)
                else:
                    tot += rec(S, r - 1) if False else rec(T, r - 1)
            memo[key] = tot
            return tot

        res = rec(self.full, k)
        return res, len(memo)

    # ---- enumeration of all sorter sequences of length k (as tuples of comp idx)
    def enumerate(self, k, first=None):
        out = []
        sm = self.sortedmask
        n1 = self.n + 1
        feas = {}

        def can(S, r):
            if not (S & ~sm):
                return True
            if r == 0:
                return False
            pc = bin(S).count('1')
            need = 0
            x = pc
            while x > n1:
                x = (x + 1) // 2
                need += 1
            if need > r:
                return False
            key = (S, r)
            g = feas.get(key)
            if g is not None:
                return g
            v = False
            for ci in range(self.m):
                if can(self.apply(ci, S), r - 1):
                    v = True
                    break
            feas[key] = v
            return v

        path = []

        def rec(S, r):
            if r == 0:
                if not (S & ~sm):
                    out.append(tuple(path))
                return
            for ci in range(self.m):
                T = self.apply(ci, S)
                if can(T, r - 1):
                    path.append(ci)
                    rec(T, r - 1)
                    path.pop()

        if first is None:
            rec(self.full, k)
        else:
            path.append(first)
            rec(self.apply(first, self.full), k - 1)
            path.pop()
        return out

    def sorts(self, seq):
        S = self.full
        for ci in seq:
            S = self.apply(ci, S)
        return not (S & ~self.sortedmask)


# ---------- generalized networks, relabel + untangle ----------
def untangle(pairs, n):
    """pairs: list of directed comparators (a,b) meaning min->a, max->b.
    Returns standard-form (a<b) network with same sorting behaviour."""
    out = []
    perm = list(range(n))  # current relabelling applied to remaining comparators
    for (a, b) in pairs:
        a2, b2 = perm[a], perm[b]
        if a2 < b2:
            out.append((a2, b2))
        else:
            out.append((b2, a2))
            # swap roles of channels a2,b2 for all subsequent comparators
            for t in range(n):
                if perm[t] == a2:
                    perm[t] = b2
                elif perm[t] == b2:
                    perm[t] = a2
    return out


def relabel(pairs, sigma):
    return [(sigma[a], sigma[b]) for (a, b) in pairs]


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('--mode', default='counts')
    ap.add_argument('--n', type=int, default=4)
    ap.add_argument('--k', type=int, default=5)
    a = ap.parse_args()
    if a.mode == 'counts':
        for (n, k) in [(4, 4), (4, 5), (4, 6), (5, 8), (5, 9), (3, 3)]:
            t = time.time()
            net = Net(n)
            c, ms = net.count(k)
            print(f"N({n},{k}) = {c}   memo={ms}  {time.time()-t:.2f}s")
    elif a.mode == 'first':
        net = Net(a.n)
        tot = 0
        for ci, c in enumerate(net.comps):
            e = net.enumerate(a.k, first=ci)
            print(f"  first={c}: {len(e)}")
            tot += len(e)
        print("total", tot)


if __name__ == '__main__':
    main()

